from jsonb_to_recordset($json$[{"id":"che-ek-186","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"If 0.635 g of copper is plated from CuSO$_4$ in 1930 s, the steady current used was","options":["$1.0\\ \\mathrm{A}$","$0.50\\ \\mathrm{A}$","$2.0\\ \\mathrm{A}$","$0.10\\ \\mathrm{A}$"],"answer_index":0,"explanation":"$Q = (0.635 \\times 2 \\times 96500)/63.5 = 1930\\ \\mathrm{C}$; $I = Q/t = 1930/1930 = 1.0\\ \\mathrm{A}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"electrolysis-faraday","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-187","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A current of 2.0 A is passed for 30 min through molten Al$_2$O$_3$ (Al = 27). The mass of aluminium liberated is","options":["$0.336\\ \\mathrm{g}$","$1.008\\ \\mathrm{g}$","$0.112\\ \\mathrm{g}$","$9.00\\ \\mathrm{g}$"],"answer_index":0,"explanation":"$Q = 2.0 \\times 1800 = 3600\\ \\mathrm{C}$. $m = (27 \\times 3600)/(3 \\times 96500) \\approx 0.336\\ \\mathrm{g}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"electrolysis-faraday","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-188","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The same current flows for the same time through AgNO$_3$ and then, separately, through AuCl$_3$ (Au = 197). If 1.08 g Ag is deposited, the gold deposited is nearest","options":["$0.657\\ \\mathrm{g}$","$1.97\\ \\mathrm{g}$","$0.328\\ \\mathrm{g}$","$3.00\\ \\mathrm{g}$"],"answer_index":0,"explanation":"Equal charge means equal equivalents: $m_{\\mathrm{Au}}/m_{\\mathrm{Ag}} = (197/3)/108$, so $m_{\\mathrm{Au}} = 1.08 \\times 197/(3 \\times 108) = 0.657\\ \\mathrm{g}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"electrolysis-faraday","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-189","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A primary electrochemical cell is one that","options":["cannot be recharged by reversing the current","is recharged simply by plugging it into the mains","has no electrode at all","works only as an electrolytic cell"],"answer_index":0,"explanation":"Once the reductant and oxidant of a dry cell or button cell are spent, the cell is discarded.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"batteries-corrosion","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-190","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A secondary cell differs from a primary cell in that it","options":["can be recharged because the cell reaction is reversible","never involves a redox change","has $E = 0$ at all times","must be discarded after a single use"],"answer_index":0,"explanation":"Lead–acid and Ni–Cd cells are secondary batteries: charging drives the discharge reaction backwards.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"batteries-corrosion","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-191","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The common dry cell (Leclanché) uses a zinc cup as the anode and, as the cathode depolariser,","options":["manganese dioxide packed around a carbon rod","lead dioxide on a lead grid","porous platinum and hydrogen gas","solid sodium chloride only"],"answer_index":0,"explanation":"Zn is oxidised; MnO$_2$ is reduced at the carbon collector in the NH$_4$Cl / ZnCl$_2$ paste.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"batteries-corrosion","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-192","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A hydrogen–oxygen fuel cell is designed so that the reactants are","options":["fed continuously, and the cell can run as long as fuel and oxidant are supplied","sealed once and for all inside a closed can","generated only by charging overnight","the same as those of a lead storage battery"],"answer_index":0,"explanation":"A fuel cell is a galvanic cell with continuous feeds; it is not a store of a finite charge like a battery.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"batteries-corrosion","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-193","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Rusting of iron is classified as an electrochemical process because it involves","options":["local anodic oxidation of Fe and cathodic reduction of dissolved oxygen","a purely mechanical wearing away of the metal","melting of iron below 100 °C","photochemical cleavage of Fe–Fe bonds only"],"answer_index":0,"explanation":"Different surface spots act as tiny galvanic cells in the presence of a water film containing O$_2$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"batteries-corrosion","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-194","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Ordinary rusting of iron requires, besides the metal itself,","options":["both moisture and oxygen","oxygen in a completely dry atmosphere only","a vacuum and ultraviolet light","solid NaCl with no water at all"],"answer_index":0,"explanation":"Water provides the ionic medium; oxygen is the cathodic oxidant. Dry iron in air rusts extremely slowly.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"batteries-corrosion","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-195","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"During discharge of a lead storage battery the electrolyte H$_2$SO$_4$ is consumed and the product deposited on both plates is","options":["lead(II) sulphate","lead metal only","lead dioxide only","elemental sulphur"],"answer_index":0,"explanation":"Pb + PbO$_2$ + 2 H$_2$SO$_4$ → 2 PbSO$_4$ + 2 H$_2$O. Charging reverses this reaction and regenerates acid.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"batteries-corrosion","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
